$fn = 128;

belt_width = 6;
bearing_od = 16;
bearing_id = 5;
bearing_width = 5;
body_d = 18;
flange_d = 22;
flange_h = 1.5;
total_h = belt_width + 2 * flange_h;

module gt2_smooth_bearing_idler() {
    difference() {
        union() {
            cylinder(h = belt_width, d = body_d, center = true);
            translate([0, 0, total_h/2 - flange_h/2])
                cylinder(h = flange_h, d = flange_d, center = true);
            translate([0, 0, -total_h/2 + flange_h/2])
                cylinder(h = flange_h, d = flange_d, center = true);
        }
        cylinder(h = total_h + 2, d = bearing_od, center = true);
    }
}

gt2_smooth_bearing_idler();

