// GT2 2mm smooth bearing idler pulley — 624ZZ bearing, 6 mm belt
// STANDALONE — no include required

// ── MAIN PARAMETERS ──
bearing_OD    = 13.0;   // mm — 624ZZ outer diameter
bearing_bore  = 4.0;    // mm — 624ZZ inner bore (M4 shoulder bolt passes through)
bearing_width = 5.0;    // mm — 624ZZ axial width
belt_width    = 6.0;    // mm — GT2 standard belt width

// ── SECONDARY PARAMETERS ──
wall          = 1.5;    // mm — sleeve wall over bearing OD
flange_h      = 1.0;    // mm — radial overhang of retention shoulder above belt surface
flange_t      = 1.2;    // mm — axial thickness of each retention shoulder
bore_tol      = -0.10;  // mm — interference: sleeve bore = bearing_OD + bore_tol
                        //      use -0.10 for 3D print; 0.00 for machined press fit

// ── DERIVED PARAMETERS ──
sleeve_OD      = bearing_OD + 2 * wall;           // = 16.0 mm  belt contact diameter
sleeve_bore    = bearing_OD + bore_tol;           // = 12.9 mm  press fit onto bearing OD
flange_OD      = sleeve_OD + 2 * flange_h;        // = 18.0 mm  retention shoulder OD
total_h        = belt_width + 2 * flange_t;       // = 8.4 mm   total sleeve height

$fn = 128;

module gt2_smooth_idler_624zz() {
    difference() {
        union() {
            // Belt contact zone — smooth cylinder, no teeth
            cylinder(h = belt_width, d = sleeve_OD, center = true);

            // Bottom retention flange — prevents belt falling off downward
            translate([0, 0, -(belt_width/2 + flange_t/2)])
                cylinder(h = flange_t, d = flange_OD, center = true);

            // Top retention flange — prevents belt riding off upward
            translate([0, 0, belt_width/2 + flange_t/2])
                cylinder(h = flange_t, d = flange_OD, center = true);
        }

        // Inner bore — press fit onto bearing OD
        // sleeve_bore < bearing_OD: negative tolerance gives interference fit
        cylinder(h = total_h + 2, d = sleeve_bore, center = true, $fn = 96);
    }
}

gt2_smooth_idler_624zz();
